-- ══════════════════════════════════════════════════════════════
--  IMPORTAÇÃO DO BACKUP DO FIREBASE → SUPABASE
--  Origem: backup_gas_2026-07-30_15-46.json
--  2070 lançamentos, 75 cargas
--  Rode este script INTEIRO no SQL Editor do Supabase, DEPOIS de
--  já ter rodado o supabase_setup.sql (que cria as tabelas roberto_*).
-- ══════════════════════════════════════════════════════════════

begin;

-- ── Lançamentos ──────────────────────────────────────────────
on conflict (id) do update set data = excluded.data, updated_at = now();

-- ── Cargas ───────────────────────────────────────────────────
on conflict (id) do update set data = excluded.data, updated_at = now();

-- ── Configurações (preços, frete, dias por empresa) ──────────
on conflict (id) do update set data = excluded.data, updated_at = now();

commit;

-- ── Conferência rápida ────────────────────────────────────────
select 'roberto_lancamentos' as tabela, count(*) from public.roberto_lancamentos
union all
select 'roberto_cargas', count(*) from public.roberto_cargas
union all
select 'roberto_config', count(*) from public.roberto_config;